package com.eidolon.sc.mobile;
import java.time.*;import java.util.*;import org.json.*;

/** Source-linked conversational effects in existing life goals/events; no model or relationship calls. */
final class ContinuityLife {
 static final int MAX_LINKS=12;
 static long version(JSONObject o){return o.optLong("version",1);}
 static boolean open(JSONObject g){return g!=null&&Arrays.asList("active","paused").contains(g.optString("status"));}
 static void note(JSONObject g,String action,String detail,String ref,long messageId,long now)throws Exception{
  g.put("version",version(g)+1).put("updatedAt",now);JSONArray log=g.optJSONArray("journey");if(log==null)log=new JSONArray();
  log.put(new JSONObject().put("action",action).put("text",MediaData.cut(detail,180)).put("eventId",ref).put("messageId",messageId).put("at",now).put("version",version(g)).put("progress",g.optInt("progress")).put("status",g.optString("status")).put("method",g.optString("method")));while(log.length()>10)log.remove(0);g.put("journey",log);
 }
 static void seeded(JSONObject s,JSONObject g,long now)throws Exception{g.put("version",1).put("createdAt",now).put("updatedAt",now).put("source","generated_virtual_goal").put("sourceMessageId",0).put("journey",new JSONArray());}
 static void progress(JSONObject s,JSONObject g,JSONObject child,long now)throws Exception{g.put("latestProgress",child.getString("title")).put("lastProgressAt",now);note(g,"progress",child.getString("title"),child.getString("id"),0,now);}
 static JSONArray links(JSONObject state){JSONArray out=new JSONArray(),all=state.optJSONArray("events");if(all!=null)for(int i=0;i<all.length();i++){JSONObject e=all.optJSONObject(i);if(e!=null&&e.optString("kind").equals("exchange"))out.put(e);}return out;}
 static void bind(JSONObject state,JSONObject a)throws Exception{
  if(!a.optString("kind").equals("activity")||!Arrays.asList("planned","paused","in_progress").contains(a.optString("status")))return;
  JSONObject g=LifeData.find(state.optJSONArray("goals"),a.optString("goalId"));if(g==null||!g.optString("status").equals("active")||a.optInt("goalStep",-1)!=g.optInt("progress"))return;
  JSONArray applied=new JSONArray(),all=links(state);for(int i=0;i<all.length()&&applied.length()<2;i++){JSONObject e=all.getJSONObject(i);if(e.optString("exchangeStatus").equals("planned")&&!e.optBoolean("sourceMissing")&&e.optString("goalId").equals(g.getString("id"))&&e.optInt("goalStep",-1)==a.getInt("goalStep")&&e.optLong("intentAt")>0&&e.getLong("intentAt")<=a.optLong("start"))applied.put(e.getString("id"));}a.put("appliedAdviceIds",applied);
 }
 static void observed(JSONObject s,JSONObject a,long now)throws Exception{
  if(!a.optString("status").equals("completed")||!a.optString("source").equals("simulation_rule"))return;JSONArray applied=a.optJSONArray("appliedAdviceIds");if(applied==null)return;JSONObject g=LifeData.find(s.optJSONArray("goals"),a.optString("goalId"));if(g==null)return;
  for(int i=0;i<applied.length();i++){JSONObject e=LifeData.find(s.getJSONArray("events"),applied.getString(i));if(e==null||!e.optString("exchangeStatus").equals("planned")||e.optLong("intentAt")>a.getLong("start")||e.optBoolean("sourceMissing"))continue;
   e.put("exchangeStatus","tried").put("status","completed").put("trialEventId",a.getString("id")).put("trialAt",now).put("trialProgress",g.optInt("progress")).put("at",now).put("result","已完成一次「"+a.getString("title")+"」的虚拟尝试；具体效果尚未记录").put("version",version(e)+1).put("resultSource","simulation_rule");note(g,"try_advice","在本次虚拟活动中试用了用户建议",a.getString("id"),e.optLong("sourceMessageId"),now);
  }
 }
 static void reclaimWithdrawn(JSONObject s)throws Exception{JSONArray all=s.getJSONArray("events");Set<String> removed=new HashSet<>();for(int i=all.length()-1;i>=0;i--){JSONObject e=all.getJSONObject(i);if(e.optString("kind").equals("exchange")&&e.optString("exchangeStatus").equals("withdrawn")){removed.add(e.getString("id"));all.remove(i);}}JSONArray goals=s.getJSONArray("goals");for(int i=0;i<goals.length();i++){JSONArray log=goals.getJSONObject(i).optJSONArray("journey");if(log!=null)for(int r=log.length()-1;r>=0;r--)if(removed.contains(log.getJSONObject(r).optString("eventId")))log.remove(r);}}
 static JSONObject source(JSONObject frame,long id){return LifeData.find(frame.optJSONArray("sources"),""+id);}
 static ChatStore.Message actual(JSONObject frame,List<ChatStore.Message> history,long id,String quote,String role){JSONObject r=source(frame,id);if(r==null||!r.optString("role").equals(role)||!r.optString("text").contains(quote))return null;return UserUnderstanding.evidence(history,id,quote,role);}
 static boolean uttered(String answer,String quote,int max){return quote!=null&&quote.trim().length()>=2&&quote.length()<=max&&answer.contains(quote);}
 static boolean futureAttempt(String quote){return quote.matches("(?s).*(试试|试一下|尝试一下|打算|准备|試して|やってみ|試そう).*")&&!quote.matches("(?s).*(已经试|试过了|试了一|試した).*");}
 static JSONObject raw(String raw)throws Exception{String t=raw.trim();if(t.length()>6&&t.charAt(0)==96&&t.charAt(t.length()-1)==96){int n=t.indexOf('\n');if(n>0)t=t.substring(n+1,t.length()-3).trim();}return t.startsWith("{")?new JSONObject(t):new JSONObject();}
 static JSONObject stage(String raw,String answer,JSONObject frame,List<ChatStore.Message> history)throws Exception{
  JSONObject out=new JSONObject().put("frame",frame).put("operations",new JSONArray()).put("mentions",new JSONArray()).put("goalMentions",new JSONArray());if(!frame.optBoolean("enabled")||!frame.optBoolean("lifeEnabled"))return out;JSONObject data=raw(raw).optJSONObject("continuity");if(data==null)return out;JSONArray ops=out.getJSONArray("operations"),advice=data.optJSONArray("suggestions");
  if(advice!=null)for(int i=0;i<Math.min(1,advice.length());i++){
   JSONObject p=advice.getJSONObject(i),g=LifeData.find(frame.optJSONArray("goals"),p.optString("goalId"));if(g==null||!g.optString("status").equals("active")||g.optLong("version")!=p.optLong("goalVersion")||g.optInt("progress")!=p.optInt("stage",-1))continue;
   String evidence=p.optString("evidence"),quote=p.optString("quote"),decision=p.optString("decision");ChatStore.Message m=actual(frame,history,p.optLong("sourceId"),evidence,"user");if(m==null||!uttered(answer,quote,300)||!Arrays.asList("consider","try_later").contains(decision)||decision.equals("try_later")&&!futureAttempt(quote))continue;
   String problem=p.optString("problemQuote");ChatStore.Message earlier=actual(frame,history,p.optLong("problemSourceId"),problem,"assistant");JSONObject issue=LifeData.find(g.optJSONArray("difficulties"),p.optString("problemId"));if((earlier==null||earlier.sentAt>m.sentAt)&&issue==null)continue;
   String method=p.optString("method",evidence).trim();if(method.isEmpty()||method.length()>160||!evidence.contains(method))continue;
   ops.put(new JSONObject().put("kind","suggestion").put("goalId",g.getString("id")).put("goalVersion",g.getLong("version")).put("stage",g.getInt("progress")).put("sourceMessageId",m.id).put("sourceAt",m.sentAt).put("sourceZone",m.zone).put("advice",evidence).put("method",method).put("problemSourceId",earlier==null?0:earlier.id).put("problemQuote",earlier==null?"":problem).put("problemId",issue==null?"":issue.getString("id")).put("decision",decision).put("quote",quote));
  }
  JSONArray actions=data.optJSONArray("actions");if(actions!=null)for(int i=0;i<Math.min(2,actions.length());i++){
   JSONObject p=actions.getJSONObject(i);String op=p.optString("operation"),quote=p.optString("quote"),reason=p.optString("reason",quote);if(!uttered(answer,quote,300)||reason.isEmpty()||reason.length()>160||!answer.contains(reason))continue;
   if(op.equals("adopt")){JSONObject e=LifeData.find(frame.optJSONArray("callbacks"),p.optString("id"));if(e==null||!e.optString("exchangeStatus").equals("suggested")||e.optLong("version")!=p.optLong("version")||!futureAttempt(quote))continue;ops.put(new JSONObject().put("kind","adopt").put("id",e.getString("id")).put("version",e.getLong("version")).put("quote",quote));continue;}
   JSONObject g=LifeData.find(frame.optJSONArray("goals"),p.optString("id"));if(g==null||!open(g)||g.optLong("version")!=p.optLong("version")||!Arrays.asList("adjust","pause","resume","cancel").contains(op))continue;if(op.equals("resume")&&!g.optString("status").equals("paused")||op.equals("pause")&&!g.optString("status").equals("active"))continue;
   String method=p.optString("method");if(method.length()>160||!method.isEmpty()&&!answer.contains(method))continue;ops.put(new JSONObject().put("kind",op).put("id",g.getString("id")).put("version",g.getLong("version")).put("reason",reason).put("method",method).put("quote",quote));
  }
  JSONArray results=data.optJSONArray("reflections");if(results!=null)for(int i=0;i<Math.min(1,results.length());i++){JSONObject p=results.getJSONObject(i),e=LifeData.find(frame.optJSONArray("callbacks"),p.optString("id"));String result=p.optString("result"),next=p.optString("nextStep");JSONObject goal=e==null?null:LifeData.find(frame.optJSONArray("goals"),e.optString("goalId"));if(goal!=null&&goal.optBoolean("externalResultRequired")&&result.matches("(?s).*(赢了比赛|比赛赢了|获奖了|通过了考试|考试通过了|录取了|優勝した|合格した).*"))continue;if(e!=null&&e.optString("exchangeStatus").equals("tried")&&e.optString("resultSource").equals("simulation_rule")&&e.optLong("version")==p.optLong("version")&&uttered(answer,result,160)&&next.length()<=100&&(next.isEmpty()||answer.contains(next)))ops.put(new JSONObject().put("kind","reflection").put("id",e.getString("id")).put("version",e.getLong("version")).put("result",result).put("nextStep",next));}
  JSONArray habits=data.optJSONArray("habits");if(habits!=null)for(int i=0;i<Math.min(1,habits.length());i++){JSONObject p=habits.getJSONObject(i);String evidence=p.optString("evidence"),text=p.optString("text"),quote=p.optString("quote");ChatStore.Message m=actual(frame,history,p.optLong("sourceId"),evidence,"user");if(m!=null&&evidence.matches("(?s).*(叫我|称呼我|以后.*叫|下次.*(分享|告诉)|咱们.*(叫|梗)).*")&&text.length()>=2&&text.length()<=100&&evidence.contains(text)&&uttered(answer,quote,300))ops.put(new JSONObject().put("kind","habit").put("sourceMessageId",m.id).put("sourceAt",m.sentAt).put("sourceZone",m.zone).put("evidence",evidence).put("text",text).put("quote",quote));}
  JSONArray mentions=data.optJSONArray("mentions");if(mentions!=null)for(int i=0;i<Math.min(2,mentions.length());i++){JSONObject p=mentions.getJSONObject(i),e=LifeData.find(frame.optJSONArray("callbacks"),p.optString("id"));String quote=p.optString("quote");if(e!=null&&e.optLong("version")==p.optLong("version")&&uttered(answer,quote,300))out.getJSONArray("mentions").put(new JSONObject().put("id",e.getString("id")).put("version",e.getLong("version")).put("quote",quote));}
  JSONArray goalMentions=data.optJSONArray("goalMentions");if(goalMentions!=null)for(int i=0;i<Math.min(1,goalMentions.length());i++){JSONObject m=goalMentions.getJSONObject(i),g=LifeData.find(frame.optJSONArray("goals"),m.optString("id"));if(g!=null&&g.optLong("version")==m.optLong("version")&&g.optString("progressKey").equals(m.optString("progressKey"))&&uttered(answer,m.optString("quote"),300))out.getJSONArray("goalMentions").put(new JSONObject(m.toString()));}return out;
 }
 static boolean deliver(JSONObject s,JSONObject effect,String answer,long messageId,long now)throws Exception{
  if(effect==null||!s.optBoolean("enabled")||messageId<=s.optLong("continuityDeliveredThrough"))return false;reclaimWithdrawn(s);JSONArray ops=effect.optJSONArray("operations"),mentions=effect.optJSONArray("mentions");boolean changed=false;
  if(ops!=null)for(int i=0;i<ops.length();i++){JSONObject p=ops.getJSONObject(i);String kind=p.getString("kind");
   if(kind.equals("suggestion")){
    JSONObject g=LifeData.find(s.getJSONArray("goals"),p.getString("goalId"));if(g==null||!g.optString("status").equals("active")||version(g)!=p.getLong("goalVersion")||g.getInt("progress")!=p.getInt("stage"))continue;
    String id="exchange/"+s.getString("character")+"/"+p.getLong("sourceMessageId")+"/"+VoiceCache.digest(g.getString("id")+"/"+g.getInt("progress")+"/"+p.getString("advice")).substring(0,16);if(LifeData.find(s.getJSONArray("events"),id)!=null||links(s).length()>=MAX_LINKS)continue;
    JSONObject e=LifeData.event(id,MediaData.cut(p.getString("advice"),160),"exchange",0,0,g.getString("id")).put("status","open").put("at",now).put("source","shared_conversation").put("subject","character").put("version",1).put("eventVersion",1).put("goalId",g.getString("id")).put("goalStep",p.getInt("stage")).put("scope",s.getString("character")).put("exchangeStatus",p.getString("decision").equals("try_later")?"planned":"suggested").put("sourceMessageId",p.getLong("sourceMessageId")).put("sourceAt",p.getLong("sourceAt")).put("sourceZone",p.getString("sourceZone")).put("advice",p.getString("advice")).put("method",p.getString("method")).put("problemId",p.getString("problemId")).put("problemSourceId",p.getLong("problemSourceId")).put("problemQuote",p.getString("problemQuote")).put("replyMessageId",messageId).put("intentQuote",p.getString("quote")).put("intentAt",p.getString("decision").equals("try_later")?now:0);
    s.getJSONArray("events").put(e);note(g,"user_suggestion",p.getString("advice"),id,p.getLong("sourceMessageId"),now);changed=true;
   }else if(kind.equals("habit")){
    String id="exchange/"+s.getString("character")+"/habit/"+p.getLong("sourceMessageId");if(LifeData.find(s.getJSONArray("events"),id)!=null||links(s).length()>=MAX_LINKS)continue;
    s.getJSONArray("events").put(LifeData.event(id,p.getString("text"),"exchange",0,0,"").put("status","completed").put("exchangeStatus","habit").put("scope",s.getString("character")).put("version",1).put("at",now).put("source","shared_conversation").put("sourceMessageId",p.getLong("sourceMessageId")).put("sourceAt",p.getLong("sourceAt")).put("sourceZone",p.getString("sourceZone")).put("advice",p.getString("evidence")).put("replyMessageId",messageId).put("intentQuote",p.getString("quote")));changed=true;
   }else if(Arrays.asList("reflection","adopt").contains(kind)){
    JSONObject e=LifeData.find(s.getJSONArray("events"),p.getString("id"));if(e==null||version(e)!=p.getLong("version")||e.optBoolean("sourceMissing"))continue;
    if(kind.equals("adopt")&&e.optString("exchangeStatus").equals("suggested"))e.put("exchangeStatus","planned").put("intentAt",now).put("intentQuote",p.getString("quote")).put("replyMessageId",messageId);
    else if(kind.equals("reflection")&&e.optString("exchangeStatus").equals("tried")&&e.optString("resultSource").equals("simulation_rule"))e.put("result",p.getString("result")).put("nextStep",p.getString("nextStep")).put("resultSource","generated_virtual_reflection").put("resultMessageId",messageId);else continue;e.put("version",version(e)+1).put("eventVersion",e.optLong("eventVersion",1)+1);if(kind.equals("reflection")){e.put("sharedVersion",version(e)).put("sharedAt",now).put("sharedMessageId",messageId);markGoalShared(s,e,now);}changed=true;
   }else{
    JSONObject g=LifeData.find(s.getJSONArray("goals"),p.getString("id"));if(!open(g)||version(g)!=p.getLong("version"))continue;if(kind.equals("resume")&&!g.optString("status").equals("paused")||kind.equals("pause")&&!g.optString("status").equals("active"))continue;
    JSONObject root=LifeData.find(s.getJSONArray("events"),g.getString("id"));if(kind.equals("pause"))g.put("status","paused").put("pauseReason",p.getString("reason"));else if(kind.equals("resume")){g.put("status","active");g.remove("pauseReason");}else if(kind.equals("cancel"))g.put("status","cancelled").put("closedReason",p.getString("reason"));
    if(!p.optString("method").isEmpty())g.put("method",p.getString("method"));if(root!=null)root.put("status",g.getString("status").equals("active")?"open":g.getString("status")).put("eventVersion",root.optLong("eventVersion",1)+1);note(g,kind,p.getString("reason"),g.getString("id"),messageId,now);changed=true;
   }
  }
  if(mentions!=null)for(int i=0;i<mentions.length();i++){JSONObject m=mentions.getJSONObject(i),e=LifeData.find(s.getJSONArray("events"),m.getString("id"));if(e!=null&&version(e)==m.getLong("version")&&answer.contains(m.getString("quote"))){e.put("sharedVersion",version(e)).put("sharedAt",now).put("sharedMessageId",messageId);markGoalShared(s,e,now);changed=true;}}
  JSONArray gm=effect.optJSONArray("goalMentions");if(gm!=null)for(int i=0;i<gm.length();i++){JSONObject m=gm.getJSONObject(i),g=LifeData.find(s.getJSONArray("goals"),m.optString("id"));if(g!=null&&ContinuityContext.progressKey(g).equals(m.optString("progressKey"))&&answer.contains(m.optString("quote"))){g.put("sharedProgressKey",m.getString("progressKey")).put("sharedProgressAt",now);changed=true;}}
  JSONObject frame=effect.optJSONObject("frame"),offered=frame==null?null:frame.optJSONObject("selected");if(offered!=null){boolean goal=offered.optString("kind").equals("goal_progress");JSONObject record=LifeData.find(s.optJSONArray(goal?"goals":"events"),offered.optString("id"));if(record!=null){if(goal&&ContinuityContext.progressKey(record).equals(offered.optString("progressKey")))record.put("offeredProgressKey",offered.getString("progressKey"));else if(!goal&&version(record)==offered.optLong("version")){record.put("offeredVersion",version(record));JSONObject g=LifeData.find(s.getJSONArray("goals"),record.optString("goalId"));if(g!=null&&g.optInt("progress")==record.optInt("trialProgress",-1)&&g.optLong("lastProgressAt")==record.optLong("trialAt"))g.put("offeredProgressKey",ContinuityContext.progressKey(g));}changed=true;}}
  if(changed)s.put("continuityDeliveredThrough",messageId);return changed;
 }
 static boolean supportsReach(JSONObject state,JSONObject effect){JSONObject frame=effect==null?null:effect.optJSONObject("frame"),selected=frame==null?null:frame.optJSONObject("selected");if(selected==null)return false;String id=selected.optString("id");JSONObject e=LifeData.find(state.optJSONArray("events"),id);JSONArray mentions=effect.optJSONArray("mentions");if(e!=null&&e.optString("exchangeStatus").equals("tried")&&!e.optBoolean("sourceMissing")&&mentions!=null)for(int i=0;i<mentions.length();i++)if(mentions.optJSONObject(i)!=null&&mentions.optJSONObject(i).optString("id").equals(id)&&mentions.optJSONObject(i).optLong("version")==version(e))return true;JSONArray gm=effect.optJSONArray("goalMentions");JSONObject g=LifeData.find(state.optJSONArray("goals"),id);if(g!=null&&gm!=null)for(int i=0;i<gm.length();i++)if(gm.optJSONObject(i)!=null&&gm.optJSONObject(i).optString("id").equals(id)&&gm.optJSONObject(i).optString("progressKey").equals(ContinuityContext.progressKey(g)))return true;return false;}
 static void markGoalShared(JSONObject s,JSONObject e,long now)throws Exception{JSONObject g=LifeData.find(s.getJSONArray("goals"),e.optString("goalId"));if(g!=null&&g.optInt("progress")==e.optInt("trialProgress",-1)&&g.optLong("lastProgressAt")==e.optLong("trialAt"))g.put("sharedProgressKey",ContinuityContext.progressKey(g)).put("sharedProgressAt",now);}
 static void validate(JSONObject state)throws Exception{
  if(links(state).length()>MAX_LINKS)throw new Exception("共同经历记录过多");JSONArray goals=state.getJSONArray("goals");
  for(int i=0;i<goals.length();i++){JSONObject g=goals.getJSONObject(i);if(version(g)<1||g.optString("method").length()>160||g.optString("pauseReason").length()>160||g.optString("closedReason").length()>160)throw new Exception("目标进展依据无效");JSONArray log=g.optJSONArray("journey");if(log!=null){if(log.length()>10)throw new Exception("目标经过过多");for(int r=0;r<log.length();r++)if(log.getJSONObject(r).optString("text").length()>180||log.getJSONObject(r).optLong("at")<0)throw new Exception("目标经过来源无效");}}
  JSONArray all=links(state);for(int i=0;i<all.length();i++){JSONObject e=all.getJSONObject(i);if(!e.optString("scope").equals(state.getString("character"))||!Arrays.asList("suggested","planned","tried","habit","withdrawn").contains(e.optString("exchangeStatus"))||e.optLong("sourceMessageId")<=0&&!e.optBoolean("sourceMissing")||version(e)<1||e.optString("advice").length()>600||e.optString("result").length()>200||e.optString("method").length()>160||e.optString("problemQuote").length()>600)throw new Exception("共同经历来源或状态无效");ZoneId.of(e.getString("sourceZone"));if(e.optString("exchangeStatus").equals("tried")&&(e.optString("trialEventId").isEmpty()||e.optLong("trialAt")<=0||e.optLong("intentAt")<=0))throw new Exception("共同经历缺少尝试依据");}
 }
 private ContinuityLife(){}
}
